RIDES = [('Shambhala', 'thrill coaster'), ('Dragon Khan', 'thrill coaster'), ('Red Force', 'thrill coaster'), ('Furius Baco', 'thrill coaster'), ('Uncharted', 'dark ride')]
print('Ride-type classifier: PortAventura World')
counts = {}
for name, kind in RIDES:
    counts[kind] = counts.get(kind, 0) + 1
for kind in sorted(counts):
    print("%s: %d" % (kind, counts[kind]))
print("Operating rides classified: %d" % len(RIDES))

